<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Ground-Mounted Photovoltaic Module</title>
  <style>
    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
      color: #f4f7f8;
      background:
        radial-gradient(circle at 50% 20%, #edf4f7 0%, #c7d4da 58%, #91a4ad 100%);
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      touch-action: none;
      outline: none;
    }

    .info {
      position: fixed;
      top: 24px;
      left: 24px;
      z-index: 2;
      max-width: 330px;
      padding: 17px 19px;
      border: 1px solid rgba(255, 255, 255, 0.28);
      border-radius: 14px;
      background: rgba(24, 35, 42, 0.72);
      box-shadow: 0 12px 35px rgba(24, 35, 42, 0.2);
      backdrop-filter: blur(12px);
      pointer-events: none;
    }

    .eyebrow {
      margin-bottom: 5px;
      color: #83c9a6;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.18em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: 20px;
      line-height: 1.2;
      letter-spacing: -0.02em;
    }

    .info p {
      margin: 9px 0 0;
      color: rgba(244, 247, 248, 0.68);
      font-size: 12px;
      line-height: 1.5;
    }

    .controls {
      position: fixed;
      right: 22px;
      bottom: 20px;
      z-index: 3;
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 10px 12px;
      border: 1px solid rgba(255, 255, 255, 0.24);
      border-radius: 12px;
      background: rgba(24, 35, 42, 0.68);
      box-shadow: 0 8px 24px rgba(24, 35, 42, 0.18);
      backdrop-filter: blur(10px);
      color: rgba(255, 255, 255, 0.72);
      font-size: 11px;
      user-select: none;
    }

    button {
      border: 1px solid rgba(255, 255, 255, 0.22);
      border-radius: 8px;
      padding: 7px 10px;
      background: rgba(255, 255, 255, 0.08);
      color: white;
      font: inherit;
      font-weight: 650;
      cursor: pointer;
    }

    button:hover {
      background: rgba(255, 255, 255, 0.16);
    }

    @media (max-width: 650px) {
      .info {
        top: 14px;
        left: 14px;
        right: 14px;
        max-width: none;
